begin;
set local lock_timeout = '10s';
set local statement_timeout = '60s';
select pg_advisory_xact_lock(hashtextextended('bom-historical-bulk:1806', 0));
do $record$
declare n integer;
begin
  perform 1 from public.quick_rate_collection_tracks where id=1806 and song_id is null and match_status='unresolved' for update;
  if not found then raise exception 'chart precondition failed for 1806'; end if;
  perform 1 from public.songs where id=19451 and not coalesce(is_deleted,false) and canonical_song_id='0a5b0716-545b-4171-8b00-03088aa43aa0'::uuid for update;
  if not found then raise exception 'song identity failed for 1806'; end if;
  perform 1 from public.canonical_recordings where id='c9ae11d8-ca81-4a23-ba5c-6ae72d00d5d8'::uuid and musicbrainz_recording_id is null for update;
  if not found then raise exception 'placeholder canonical precondition failed for 1806'; end if;
  if exists(select 1 from public.song_ratings where canonical_song_id='c9ae11d8-ca81-4a23-ba5c-6ae72d00d5d8'::uuid) or
     exists(select 1 from public.songs where canonical_song_id='c9ae11d8-ca81-4a23-ba5c-6ae72d00d5d8'::uuid and not coalesce(is_deleted,false)) then
    raise exception 'placeholder canonical is no longer empty for 1806';
  end if;
  update public.quick_rate_collection_tracks set song_id=19451, canonical_song_id='0a5b0716-545b-4171-8b00-03088aa43aa0'::uuid,
    musicbrainz_recording_id='6926be9f-2405-4b68-9080-42410be08312',
    match_status='direct_mbid', match_method='bulk_unique_existing',
    match_notes='Uniquely matched to existing BOM canonical recording',updated_at=timezone('utc',now()) where id=1806 and song_id is null;
  get diagnostics n=row_count; if n<>1 then raise exception 'exact chart update count failed for 1806'; end if;
end $record$;
commit;
